package com.smartsocietyconnect.announcement;
import java.time.*; import java.util.*; import java.util.stream.*; import org.springframework.http.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.*; import com.smartsocietyconnect.auth.entity.*; import com.smartsocietyconnect.auth.repository.*; import com.smartsocietyconnect.common.payload.ApiResponse; import com.smartsocietyconnect.notification.service.NotificationService;
@RestController @RequestMapping("/api/announcements") @RequiredArgsConstructor public class AnnouncementController { private final AnnouncementRepository repo; private final UserRepository users; private final UserRoleRepository userRoles; private final NotificationService notifications; record Request(@NotBlank @Size(max=150) String title,@NotBlank String message,String category,String priority,String audience,LocalDateTime publishAt,LocalDateTime expiresAt){} record Response(Integer id,String title,String message,String category,String priority,String audience,LocalDateTime publishAt,LocalDateTime expiresAt,String createdBy){}
@GetMapping public ApiResponse<List<Response>> list(){String role=role();LocalDateTime n=LocalDateTime.now();return ok(repo.findAllByOrderByPublishAtDesc().stream().filter(a->a.getPublishAt().isBefore(n)&&visible(a,role)).map(this::map).toList());}
@PostMapping public ResponseEntity<ApiResponse<Response>> create(@Valid @RequestBody Request r){manager();User me=current();Announcement a=Announcement.builder().title(r.title()).message(r.message()).category(or(r.category(),"GENERAL")).priority(or(r.priority(),"NORMAL")).audience(or(r.audience(),"ALL_RESIDENTS")).publishAt(r.publishAt()==null?LocalDateTime.now():r.publishAt()).expiresAt(r.expiresAt()).createdBy(me).build();a=repo.save(a);notifications.notifyUsers(recipients(a),"ANNOUNCEMENT",a.getPriority()+": "+a.getTitle(),a.getMessage(),"/app/announcements");return ResponseEntity.status(201).body(ok(map(a)));}
private Set<User> recipients(Announcement a){return users.findAll().stream().filter(u->visible(a,userRoles.findByUser(u).stream().map(x->x.getRole().getRoleName()).findFirst().orElse(""))).collect(Collectors.toSet());} private boolean visible(Announcement a,String r){return "ALL_RESIDENTS".equals(a.getAudience())?Set.of("RESIDENT","ADMIN","SECRETARY").contains(r):"COMMITTEE".equals(a.getAudience())?Set.of("ADMIN","SECRETARY").contains(r):a.getAudience().equals(r);} private User current(){return users.findByEmail(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();} private String role(){return userRoles.findByUser(current()).stream().map(x->x.getRole().getRoleName()).findFirst().orElse("RESIDENT");} private void manager(){if(!Set.of("ADMIN","SECRETARY").contains(role()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN);} private String or(String v,String d){return v==null||v.isBlank()?d:v;} private Response map(Announcement a){return new Response(a.getId(),a.getTitle(),a.getMessage(),a.getCategory(),a.getPriority(),a.getAudience(),a.getPublishAt(),a.getExpiresAt(),a.getCreatedBy().getFirstName());} private <T> ApiResponse<T> ok(T x){return ApiResponse.<T>builder().success(true).data(x).message("Success").build();}}
